local e = Scene.FindByName("Probe") :: Entity
local s = e:GetComponent("Script") :: Script
local behaviour = Assets.Load("Assets/Scripts/MovingPlatform.luau")
s.Scripts = {}
s.Scripts = { { Script = behaviour, Fields = { PhaseTicks = 210 }, ExecutionOrder = 0 } }
local b = e.RigidBody :: RigidBody
return { pos = e.Transform.WorldPosition, vel = b:GetLinearVelocity(), type = b.Type, scripts = #e:GetScripts() }
